cd /var/tmp/loop-bench/runs/79d6e7933ca1/workspace/target && timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage --coverageReporters=json-summary --collectCoverageFrom='src/orchestration/**/*.ts' --collectCoverageFrom='!src/**/*.test.ts' src/orchestration/tools/registry.test.ts src/orchestration/chatOrchestrator.test.ts src/orchestration/orchestratorHelpers.test.ts >/dev/null 2>&1; node -e "
const s=require('./coverage/coverage-summary.json');
let t={files:0,statements:[0,0],branches:[0,0],functions:[0,0],lines:[0,0]};
for(const [f,v] of Object.entries(s)){
  if(!f.includes('/src/orchestration/tools/')) continue;
  t.files++; console.log(f.split('src/')[1], 'stmts',v.statements.covered+'/'+v.statements.total,'br',v.branches.covered+'/'+v.branches.total,'fn',v.functions.covered+'/'+v.functions.total,'lines',v.lines.covered+'/'+v.lines.total);
  for(const k of ['statements','branches','functions','lines']){t[k][0]+=v[k].covered;t[k][1]+=v[k].total;}
}
console.log('TOOLS GROUP:', t.statements.join('/'), t.branches.join('/'), t.functions.join('/'), t.lines.join('/'));
console.log('pcts:', ['statements','branches','functions','lines'].map(k=>(100*t[k][0]/t[k][1]).toFixed(2)).join(' '));
"
